const issues = $input.first().json.issues || [];
const now = new Date();
const stuckIssues = [];
const assigneeWorkload = {};

for (const issue of issues) {
  const f = issue.fields;
  const assignee = f.assignee ? f.assignee.displayName : 'Chưa phân bổ';
  assigneeWorkload[assignee] = (assigneeWorkload[assignee] || 0) + 1;

  // Kiểm tra ticket bị kẹt > 3 ngày chưa cập nhật
  const updated = new Date(f.updated);
  const diffDays = (now - updated) / (1000 * 60 * 60 * 24);
  if (diffDays >= 3) {
    stuckIssues.push({
      key: issue.key,
      summary: f.summary,
      assignee: assignee,
      status: f.status ? f.status.name : '',
      stuckDays: Math.round(diffDays)
    });
  }
}

let reportText = `### 📋 BÁO CÁO DAILY STANDUP (${now.toISOString().split('T')[0]})\n`;
reportText += `- **Tổng số task đang mở:** ${issues.length}\n`;
reportText += `- **Cảnh báo Task bị treo (>3 ngày):** ${stuckIssues.length}\n\n`;

if (stuckIssues.length > 0) {
  reportText += `#### 🚨 Danh sách Task bị tắc nghẽn (Impediments):\n`;
  for (const s of stuckIssues) {
    reportText += `- **[${s.key}]** ${s.summary} (👤 ${s.assignee} | ⏳ ${s.stuckDays} ngày chưa cập nhật)\n`;
  }
}

return [{ json: { reportText, totalIssues: issues.length, stuckCount: stuckIssues.length } }];
